<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Auth;use App\Core\Database;use App\Core\View;use App\Services\UploadService;

final class AdminController
{
    public function dashboard():void{Auth::requirePermission('homepage.manage');$stats=['Total citizens'=>Database::one("SELECT COUNT(*) n FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.slug='citizen'")['n'],'Total civic issues'=>Database::one('SELECT COUNT(*) n FROM civic_issues WHERE deleted_at IS NULL')['n'],'Pending approvals'=>Database::one("SELECT (SELECT COUNT(*) FROM civic_issues WHERE moderation_status='pending')+(SELECT COUNT(*) FROM discussions WHERE status='pending') n")['n'],'Active discussions'=>Database::one("SELECT COUNT(*) n FROM discussions WHERE status IN('published','locked') AND deleted_at IS NULL")['n'],'Upcoming events'=>Database::one("SELECT COUNT(*) n FROM events WHERE status='published' AND starts_at>=CURRENT_TIMESTAMP")['n'],'Published articles'=>Database::one("SELECT COUNT(*) n FROM articles WHERE status='published'")['n'],'Contact enquiries'=>Database::one("SELECT COUNT(*) n FROM contact_submissions WHERE status='new'")['n'],'Volunteer requests'=>Database::one("SELECT COUNT(*) n FROM volunteer_applications WHERE status='pending'")['n']];$activities=Database::all('SELECT a.*,u.full_name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 10');View::render('admin/dashboard',compact('stats','activities'),'admin');}
    public function homepage():void{Auth::requirePermission('homepage.manage');$heroes=Database::all('SELECT * FROM hero_banners ORDER BY position,id');$strips=Database::all('SELECT * FROM scrolling_strips ORDER BY position,id');$items=Database::all('SELECT i.*,s.name strip_name FROM scrolling_strip_items i JOIN scrolling_strips s ON s.id=i.strip_id ORDER BY s.position,i.position,i.id');$announcements=Database::all('SELECT * FROM announcements ORDER BY position,id');$homepageSections=Database::all('SELECT * FROM homepage_sections ORDER BY position,id');$media=Database::all("SELECT id,original_name,file_path,alt_text FROM media_assets WHERE mime_type LIKE 'image/%' ORDER BY id DESC LIMIT 100");$linkedContent=$this->linkedContentOptions();View::render('admin/homepage',compact('heroes','strips','items','announcements','homepageSections','media','linkedContent'),'admin');}
    public function homepagePreview():void{Auth::requirePermission('homepage.manage');View::render('public/home',(new PublicController())->homeData(true));}
    public function saveHero():void{Auth::requirePermission('homepage.manage');$id=(int)($_POST['id']??0);$existing=$id?Database::one('SELECT * FROM hero_banners WHERE id=?',[$id]):null;$desktop=(new UploadService())->store($_FILES['desktop_image']??[],'homepage',true);$mobile=(new UploadService())->store($_FILES['mobile_image']??[],'homepage',true);$data=[trim($_POST['eyebrow']??''),trim($_POST['heading']??''),trim($_POST['accent_text']??''),trim($_POST['description']??''),$desktop['path']??($existing['desktop_image']??null),$mobile['path']??($existing['mobile_image']??null),trim($_POST['cta_label']??''),$this->safeDestination(trim($_POST['cta_url']??''),'hero-content'),trim($_POST['secondary_cta_label']??''),$this->safeDestination(trim($_POST['secondary_cta_url']??''),'hero-content'),$_POST['layout']??'typography',(int)($_POST['position']??0),$_POST['status']??'draft',$this->dateTimeOrNull($_POST['starts_at']??''),$this->dateTimeOrNull($_POST['ends_at']??'')];if(!$data[1]){flash('error','Hero heading is required.');redirect('admin/homepage');}if($id){Database::run('UPDATE hero_banners SET eyebrow=?,heading=?,accent_text=?,description=?,desktop_image=?,mobile_image=?,cta_label=?,cta_url=?,secondary_cta_label=?,secondary_cta_url=?,layout=?,position=?,status=?,starts_at=?,ends_at=? WHERE id=?',[...$data,$id]);$this->recordAudit('hero.updated','hero_banners',$id);}else{Database::run('INSERT INTO hero_banners(eyebrow,heading,accent_text,description,desktop_image,mobile_image,cta_label,cta_url,secondary_cta_label,secondary_cta_url,layout,position,status,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',$data);$this->recordAudit('hero.created','hero_banners',Database::id());}flash('success','Hero banner saved.');redirect('admin/homepage#hero-content');}
    public function deleteHero(string $id):void{Auth::requirePermission('homepage.manage');Database::run("UPDATE hero_banners SET status='archived' WHERE id=?",[(int)$id]);$this->recordAudit('hero.archived','hero_banners',(int)$id);flash('success','Hero banner archived.');redirect('admin/homepage');}
    public function saveStrip():void{Auth::requirePermission('homepage.manage');$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$direction=in_array($_POST['direction']??'', ['up','down'],true)?$_POST['direction']:'down';$mode=in_array($_POST['source_mode']??'', ['manual','automatic'],true)?$_POST['source_mode']:'manual';$speed=max(5,min(120,(float)($_POST['speed_seconds']??17)));$limit=max(1,min(20,(int)($_POST['source_limit']??8)));if($name===''){flash('error','Column name is required.');redirect('admin/homepage');}$data=[$name,(int)($_POST['position']??0),$direction,$speed,isset($_POST['is_visible'])?1:0,isset($_POST['mobile_enabled'])?1:0,$mode,($_POST['source_type']??'')?:null,$limit];if($id)Database::run('UPDATE scrolling_strips SET name=?,position=?,direction=?,speed_seconds=?,is_visible=?,mobile_enabled=?,source_mode=?,source_type=?,source_limit=? WHERE id=?',[...$data,$id]);else Database::run('INSERT INTO scrolling_strips(name,position,direction,speed_seconds,is_visible,mobile_enabled,source_mode,source_type,source_limit) VALUES(?,?,?,?,?,?,?,?,?)',$data);$savedId=$id?:Database::id();$this->recordAudit('strip.saved','scrolling_strips',$savedId);flash('success',$id?'Scrolling column updated.':'Scrolling column added.');redirect('admin/homepage#scrolling-columns');}
    public function deleteStrip(string $id):void{Auth::requirePermission('homepage.manage');$strip=Database::one('SELECT * FROM scrolling_strips WHERE id=?',[(int)$id]);if(!$strip){flash('error','Scrolling column not found.');redirect('admin/homepage#scrolling-columns');}Database::run('DELETE FROM scrolling_strips WHERE id=?',[(int)$id]);$this->recordAudit('strip.deleted','scrolling_strips',(int)$id);flash('success','Scrolling column and its tiles were removed.');redirect('admin/homepage#scrolling-columns');}
    public function saveMosaic():void{Auth::requirePermission('homepage.manage');$id=(int)($_POST['id']??0);if(!$id&&!consume_submission_token($_POST['submission_token']??null)){flash('error','This card was already submitted or the form expired. Please try again.');redirect('admin/homepage#scrolling-cards');}$existing=$id?Database::one('SELECT * FROM scrolling_strip_items WHERE id=?',[$id]):null;$stripId=(int)($_POST['strip_id']??0);$title=trim($_POST['title']??'');if(!$stripId||!Database::one('SELECT id FROM scrolling_strips WHERE id=?',[$stripId])||$title===''){flash('error','Choose a scrolling column and enter a card title.');redirect('admin/homepage#scrolling-cards');}$contentType=in_array($_POST['content_type']??'', ['custom','image','text','issue','discussion','event','campaign','article','cta'],true)?$_POST['content_type']:'custom';$contentId=($_POST['content_id']??'')?:null;$destination=trim($_POST['destination_url']??'');if($linked=trim($_POST['linked_record']??'')){$record=$this->resolveLinkedContent($linked);if(!$record){flash('error','The selected linked content is no longer published.');redirect('admin/homepage#scrolling-cards');}$contentType=$record['type'];$contentId=$record['id'];$destination=$record['url'];}$destination=$this->safeDestination($destination);$image=(new UploadService())->store($_FILES['image']??[],'homepage/mosaic',true);if($image)Database::run('INSERT INTO media_assets(uploader_id,original_name,file_path,mime_type,file_size,alt_text,category) VALUES(?,?,?,?,?,?,?)',[auth()['id'],$image['original'],$image['path'],$image['mime'],$image['size'],trim($_POST['alt_text']??''),'homepage']);$imagePath=$image['path']??($existing['image_path']??null);if(!$image&&($mediaPath=trim($_POST['media_path']??''))){$asset=Database::one("SELECT file_path FROM media_assets WHERE file_path=? AND mime_type LIKE 'image/%'",[$mediaPath]);if(!$asset){flash('error','Select a valid image from the Media Library.');redirect('admin/homepage#scrolling-cards');}$imagePath=$asset['file_path'];}if(isset($_POST['remove_image']))$imagePath=null;$colour=in_array($_POST['colour']??'', ['coral','yellow','blue','dark','cream'],true)?$_POST['colour']:'coral';$status=($_POST['submit_action']??'')==='draft'?'draft':(in_array($_POST['status']??'', ['draft','published','archived'],true)?$_POST['status']:'draft');$data=[$stripId,$title,trim($_POST['subtitle']??''),$contentType,$contentId,$destination,$imagePath,trim($_POST['alt_text']??''),$colour,(int)($_POST['position']??0),$status,$this->dateTimeOrNull($_POST['starts_at']??''),$this->dateTimeOrNull($_POST['ends_at']??'')];if($id)Database::run('UPDATE scrolling_strip_items SET strip_id=?,title=?,subtitle=?,content_type=?,content_id=?,destination_url=?,image_path=?,alt_text=?,colour=?,position=?,status=?,starts_at=?,ends_at=? WHERE id=?',[...$data,$id]);else Database::run('INSERT INTO scrolling_strip_items(strip_id,title,subtitle,content_type,content_id,destination_url,image_path,alt_text,colour,position,status,starts_at,ends_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',$data);$savedId=$id?:Database::id();$this->recordAudit('mosaic.saved','scrolling_strip_items',$savedId);flash('success',$status==='published'?'Scrolling card published.':'Scrolling card saved as draft.');redirect('admin/homepage#scrolling-cards');}
    public function reorderMosaic():void{Auth::requirePermission('homepage.manage');$ids=array_values(array_filter(array_map('intval',explode(',',(string)($_POST['ids']??'')))));if(!$ids){flash('error','No scrolling cards were supplied for reordering.');redirect('admin/homepage#scrolling-cards');}$placeholders=implode(',',array_fill(0,count($ids),'?'));$rows=Database::all("SELECT id,strip_id FROM scrolling_strip_items WHERE id IN ({$placeholders})",$ids);if(count($rows)!==count($ids)||count(array_unique(array_column($rows,'strip_id')))!==1){flash('error','Cards can only be reordered within the same scrolling column.');redirect('admin/homepage#scrolling-cards');}$pdo=Database::connection();$pdo->beginTransaction();try{foreach($ids as $position=>$id)Database::run('UPDATE scrolling_strip_items SET position=? WHERE id=?',[$position+1,$id]);$pdo->commit();}catch(\Throwable $e){$pdo->rollBack();throw $e;}$this->recordAudit('mosaic.reordered','scrolling_strips',(int)$rows[0]['strip_id']);flash('success','Scrolling card order saved.');redirect('admin/homepage#scrolling-cards');}
    public function toggleMosaic(string $id):void{Auth::requirePermission('homepage.manage');$item=Database::one('SELECT status FROM scrolling_strip_items WHERE id=?',[(int)$id]);if(!$item){flash('error','Scrolling card not found.');redirect('admin/homepage#scrolling-cards');}$status=$item['status']==='published'?'draft':'published';Database::run('UPDATE scrolling_strip_items SET status=? WHERE id=?',[$status,(int)$id]);$this->recordAudit('mosaic.visibility','scrolling_strip_items',(int)$id);flash('success',$status==='published'?'Scrolling card published.':'Scrolling card hidden from the public homepage.');redirect('admin/homepage#scrolling-cards');}
    public function deleteMosaic(string $id):void{Auth::requirePermission('homepage.manage');Database::run('DELETE FROM scrolling_strip_items WHERE id=?',[(int)$id]);$this->recordAudit('mosaic.deleted','scrolling_strip_items',(int)$id);flash('success','Scrolling card removed.');redirect('admin/homepage#scrolling-cards');}
    public function saveAnnouncement():void{Auth::requirePermission('homepage.manage');$id=(int)($_POST['id']??0);$data=[trim($_POST['message']??''),$this->safeDestination(trim($_POST['link_url']??''),'announcements'),$_POST['priority']??'normal',(int)($_POST['position']??0),isset($_POST['is_active'])?1:0,$this->dateTimeOrNull($_POST['starts_at']??''),$this->dateTimeOrNull($_POST['ends_at']??'')];if($id)Database::run('UPDATE announcements SET message=?,link_url=?,priority=?,position=?,is_active=?,starts_at=?,ends_at=? WHERE id=?',[...$data,$id]);else Database::run('INSERT INTO announcements(message,link_url,priority,position,is_active,starts_at,ends_at) VALUES(?,?,?,?,?,?,?)',$data);$this->recordAudit('announcement.saved','announcements',$id?:Database::id());flash('success','Announcement saved.');redirect('admin/homepage#announcements');}
    public function deleteAnnouncement(string $id):void{Auth::requirePermission('homepage.manage');Database::run('DELETE FROM announcements WHERE id=?',[(int)$id]);$this->recordAudit('announcement.deleted','announcements',(int)$id);flash('success','Scrolling announcement removed.');redirect('admin/homepage#announcements');}
    public function issues():void{Auth::requirePermission('issues.manage');$issues=Database::all('SELECT i.*,c.name category,u.full_name FROM civic_issues i JOIN issue_categories c ON c.id=i.category_id JOIN users u ON u.id=i.user_id WHERE i.deleted_at IS NULL ORDER BY i.created_at DESC LIMIT 100');View::render('admin/issues',compact('issues'),'admin');}
    public function updateIssue(string $id):void{Auth::requirePermission('issues.manage');$issue=Database::one('SELECT * FROM civic_issues WHERE id=?',[(int)$id]);if(!$issue){http_response_code(404);return;}$moderation=$_POST['moderation_status']??$issue['moderation_status'];$progress=$_POST['progress_status']??$issue['progress_status'];Database::connection()->beginTransaction();try{Database::run("UPDATE civic_issues SET moderation_status=?,progress_status=?,is_featured=?,published_at=CASE WHEN ?='approved' THEN COALESCE(published_at,CURRENT_TIMESTAMP) ELSE published_at END WHERE id=?",[$moderation,$progress,isset($_POST['is_featured'])?1:0,$moderation,(int)$id]);if($progress!==$issue['progress_status'])Database::run('INSERT INTO issue_status_history(issue_id,actor_id,previous_status,new_status,public_update,internal_notes) VALUES(?,?,?,?,?,?)',[(int)$id,auth()['id'],$issue['progress_status'],$progress,trim($_POST['public_update']??''),trim($_POST['internal_notes']??'')]);Database::run('INSERT INTO notifications(user_id,type,title,message,url) VALUES(?,?,?,?,?)',[$issue['user_id'],'issue_status','Your civic issue was updated','Moderation: '.$moderation.'; status: '.$progress,'/issues/'.$issue['slug']]);Database::connection()->commit();}catch(\Throwable $e){Database::connection()->rollBack();throw $e;}$this->recordAudit('issue.updated','civic_issues',(int)$id);flash('success','Issue updated and submitter notified.');redirect('admin/issues');}
    public function discussions():void{Auth::requirePermission('discussions.moderate');$items=Database::all('SELECT d.*,c.name category,u.full_name FROM discussions d JOIN discussion_categories c ON c.id=d.category_id JOIN users u ON u.id=d.user_id WHERE d.deleted_at IS NULL ORDER BY d.created_at DESC LIMIT 100');View::render('admin/discussions',['discussions'=>$items],'admin');}
    public function updateDiscussion(string $id):void{Auth::requirePermission('discussions.moderate');$status=$_POST['status']??'pending';Database::run("UPDATE discussions SET status=?,is_pinned=?,published_at=CASE WHEN ? IN ('published','locked') THEN COALESCE(published_at,CURRENT_TIMESTAMP) ELSE published_at END WHERE id=?",[$status,isset($_POST['is_pinned'])?1:0,$status,(int)$id]);$this->recordAudit('discussion.updated','discussions',(int)$id);flash('success','Discussion updated.');redirect('admin/discussions');}
    public function audit():void{Auth::requirePermission('audit.view');$logs=Database::all('SELECT a.*,u.full_name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT 200');View::render('admin/audit',compact('logs'),'admin');}
    private function dateTimeOrNull(string $value):?string{$value=trim($value);if($value==='')return null;$timestamp=strtotime($value);return $timestamp===false?null:date('Y-m-d H:i:s',$timestamp);}
    private function linkedContentOptions():array{return array_merge(Database::all("SELECT id,title,'issue' type,CONCAT('/issues/',slug) url FROM civic_issues WHERE moderation_status='approved' AND deleted_at IS NULL ORDER BY published_at DESC LIMIT 100"),Database::all("SELECT id,title,'discussion' type,CONCAT('/discussions/',slug) url FROM discussions WHERE status IN('published','locked') AND deleted_at IS NULL ORDER BY published_at DESC LIMIT 100"),Database::all("SELECT id,title,'event' type,CONCAT('/events/',slug) url FROM events WHERE status='published' ORDER BY starts_at DESC LIMIT 100"),Database::all("SELECT id,title,'campaign' type,CONCAT('/campaigns/',slug) url FROM campaigns WHERE status='published' ORDER BY id DESC LIMIT 100"),Database::all("SELECT id,title,'article' type,CONCAT('/articles/',slug) url FROM articles WHERE status='published' ORDER BY published_at DESC LIMIT 100"));}
    private function resolveLinkedContent(string $value):?array{if(!preg_match('/^(issue|discussion|event|campaign|article):(\d+)$/',$value,$match))return null;$type=$match[1];$id=(int)$match[2];$row=match($type){'issue'=>Database::one("SELECT id,CONCAT('/issues/',slug) url FROM civic_issues WHERE id=? AND moderation_status='approved' AND deleted_at IS NULL",[$id]),'discussion'=>Database::one("SELECT id,CONCAT('/discussions/',slug) url FROM discussions WHERE id=? AND status IN('published','locked') AND deleted_at IS NULL",[$id]),'event'=>Database::one("SELECT id,CONCAT('/events/',slug) url FROM events WHERE id=? AND status='published'",[$id]),'campaign'=>Database::one("SELECT id,CONCAT('/campaigns/',slug) url FROM campaigns WHERE id=? AND status='published'",[$id]),'article'=>Database::one("SELECT id,CONCAT('/articles/',slug) url FROM articles WHERE id=? AND status='published'",[$id]),default=>null};return $row?[...$row,'type'=>$type]:null;}
    private function safeDestination(string $value,string $anchor='scrolling-cards'):string{if($value==='')return '';$value=trim($value);if(str_starts_with($value,'/'))return '/'.ltrim($value,'/');if(filter_var($value,FILTER_VALIDATE_URL)&&in_array(strtolower((string)parse_url($value,PHP_URL_SCHEME)),['http','https'],true))return $value;flash('error','Use an internal path beginning with / or a complete HTTP or HTTPS URL.');redirect('admin/homepage#'.$anchor);}
    private function auditLogData():array{return ['ip'=>$_SERVER['REMOTE_ADDR']??null,'agent'=>substr($_SERVER['HTTP_USER_AGENT']??'',0,200)];}
    private function recordAudit(string $action,string $type,int $id):void{Database::run('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,metadata,ip_address) VALUES(?,?,?,?,?,?)',[auth()['id']??null,$action,$type,$id,json_encode($this->auditLogData()),$_SERVER['REMOTE_ADDR']??null]);}
}
